const body = $json.body ?? $json;

const question =
  typeof body.question === 'string'
    ? body.question.trim()
    : '';

const requestType =
  typeof body.requestType === 'string'
    ? body.requestType.trim()
    : '';

const logText =
  typeof body.logText === 'string'
    ? body.logText.trim()
    : '';

const sessionId =
  typeof body.sessionId === 'string' &&
  body.sessionId.trim()
    ? body.sessionId.trim()
    : 'local-demo-session';

const startedAt = Date.now();

if (!question) {
  return [
    {
      json: {
        valid: false,
        statusCode: 400,
        success: false,
        error: 'INVALID_QUESTION',
        message: '질문을 입력하세요.',
        requestType: requestType || null,
        question: '',
        logText,
        sessionId,
        startedAt,
      },
    },
  ];
}

if (
  requestType !== 'operation' &&
  requestType !== 'diagnosis'
) {
  return [
    {
      json: {
        valid: false,
        statusCode: 400,
        success: false,
        error: 'INVALID_REQUEST_TYPE',
        message:
          'requestType은 operation 또는 diagnosis여야 합니다.',
        requestType: requestType || null,
        question,
        logText,
        sessionId,
        startedAt,
      },
    },
  ];
}

return [
  {
    json: {
      valid: true,
      statusCode: 200,
      question,
      requestType,
      logText,
      sessionId,
      startedAt,
    },
  },
];

const items = $input.all();

const originalRequest =
  $('요청 검증').first().json;

const question =
  originalRequest.question ?? '';

const requestType =
  originalRequest.requestType ?? 'operation';

const logText =
  originalRequest.logText ?? '';

const sessionId =
  originalRequest.sessionId ?? 'local-demo-session';

const startedAt =
  originalRequest.startedAt ?? Date.now();

const documents = items
  .map((item, index) => {
    const json = item.json ?? {};

    const document =
      json.document ?? {};

    const metadata =
      document.metadata ?? {};

    const pageContent =
      typeof document.pageContent === 'string'
        ? document.pageContent.trim()
        : '';

    const score =
      typeof json.score === 'number'
        ? json.score
        : null;

    return {
      rank: index + 1,
      score,
      pageContent,

      documentName:
        metadata.documentName ?? '',

      title:
        metadata.title ?? '',

      category:
        metadata.category ?? '',

      section:
        metadata.section ?? '',

      chunkId:
        metadata.chunkId ?? '',

      source:
        metadata.source ?? '',
    };
  })
  .filter((doc) => doc.pageContent);

const context = documents
  .map((doc) => {
    return [
      `[검색 결과 ${doc.rank}]`,
      `문서명: ${doc.documentName}`,
      `제목: ${doc.title}`,
      `카테고리: ${doc.category}`,
      `섹션: ${doc.section}`,
      `청크 ID: ${doc.chunkId}`,
      `유사도: ${
        doc.score !== null
          ? doc.score.toFixed(4)
          : 'N/A'
      }`,
      '',
      doc.pageContent,
    ].join('\n');
  })
  .join('\n\n--------------------\n\n');

const sources = documents.map((doc) => ({
  documentName: doc.documentName,
  category: doc.category,
  section: doc.section,
  chunkId: doc.chunkId,
}));

return [
  {
    json: {
      question,
      requestType,
      logText,
      sessionId,
      startedAt,

      searchResultCount:
        documents.length,

      context,

      sources,

      retrievedDocuments:
        documents,
    },
  },
];

const requestData =
  $('운영 검색 결과 정리').first().json;

const startedAt =
  requestData.startedAt ?? Date.now();

const abstainMessage =
  '제공된 내부 자료에서는 확인할 수 없습니다.';

/*
 * true 경로:
 * 운영 답변 생성 → $json.text
 *
 * false 경로:
 * 운영 미확인 응답 → $json.answer
 */
const rawText =
  typeof $json.answer === 'string' &&
  $json.answer.trim()
    ? $json.answer.trim()
    : (
        typeof $json.text === 'string'
          ? $json.text.trim()
          : ''
      );

/*
 * 모델이 토큰 제한 때문에
 * 마지막에 "3", "3.", "3)" 같은
 * 숫자만 남기는 경우 제거
 */
function cleanIncompleteEnding(text) {
  if (!text) {
    return '';
  }

  return text
    .replace(
      /\n\s*\d+\s*[.)]?\s*$/g,
      '',
    )
    .trim();
}

const cleanedText =
  cleanIncompleteEnding(
    rawText,
  );

const finalText =
  cleanedText ||
  abstainMessage;

const isAbstained =
  finalText ===
  abstainMessage;

/*
 * false 경로에서는
 * 운영 미확인 응답이 이미 sources: [] 를 가지고 있으므로
 * 그 값을 우선 사용
 */
const rawSources =
  Array.isArray($json.sources)
    ? $json.sources
    : (
        Array.isArray(requestData.sources)
          ? requestData.sources
          : []
      );

/*
 * 동일 출처 중복 제거
 */
const uniqueSources = [];

const sourceKeys =
  new Set();

for (const source of rawSources) {
  const key = [
    source.documentName ?? '',
    source.section ?? '',
    source.chunkId ?? '',
  ].join('|');

  if (
    sourceKeys.has(key)
  ) {
    continue;
  }

  sourceKeys.add(key);

  uniqueSources.push({
    documentName:
      source.documentName ?? '',

    category:
      source.category ?? '',

    section:
      source.section ?? '',

    chunkId:
      source.chunkId ?? '',
  });
}

/*
 * false 경로에서 이미 계산된 responseTimeMs가 있으면 사용하고,
 * 아니면 여기서 계산
 */
const responseTimeMs =
  typeof $json.responseTimeMs === 'number'
    ? $json.responseTimeMs
    : Math.max(
        0,
        Date.now() - startedAt,
      );

return [
  {
    json: {
      success: true,

      requestType:
        'operation',

      question:
        requestData.question ?? '',

      answer:
        finalText,

      diagnosis:
        null,

      sources:
        isAbstained
          ? []
          : uniqueSources,

      responseTimeMs,
    },
  },
];

const items = $input.all();

const originalRequest =
  $('요청 검증').first().json;

const question =
  originalRequest.question ?? '';

const requestType =
  originalRequest.requestType ?? 'diagnosis';

const logText =
  originalRequest.logText ?? '';

const sessionId =
  originalRequest.sessionId ?? 'local-demo-session';

const startedAt =
  originalRequest.startedAt ?? Date.now();

const MIN_SIMILARITY_SCORE = 0.50;

const allDocuments = items
  .map((item, index) => {
    const json = item.json ?? {};

    const document =
      json.document ?? {};

    const metadata =
      document.metadata ?? {};

    const pageContent =
      typeof document.pageContent === 'string'
        ? document.pageContent.trim()
        : '';

    const score =
      typeof json.score === 'number'
        ? json.score
        : null;

    return {
      rank: index + 1,
      score,
      pageContent,

      documentName:
        metadata.documentName ?? '',

      title:
        metadata.title ?? '',

      category:
        metadata.category ?? '',

      section:
        metadata.section ?? '',

      chunkId:
        metadata.chunkId ?? '',

      source:
        metadata.source ?? '',
    };
  })
  .filter((doc) => doc.pageContent);

const maxSimilarityScore =
  allDocuments.length > 0
    ? Math.max(
        ...allDocuments.map((doc) =>
          typeof doc.score === 'number'
            ? doc.score
            : 0
        )
      )
    : 0;

const documents = allDocuments
  .filter((doc) => {
    if (typeof doc.score !== 'number') {
      return false;
    }

    return doc.score >= MIN_SIMILARITY_SCORE;
  })
  .map((doc, index) => ({
    ...doc,
    rank: index + 1,
  }));

const hasRelevantDocuments =
  documents.length > 0;

const context = documents
  .map((doc) => {
    return [
      `[검색 결과 ${doc.rank}]`,
      `문서명: ${doc.documentName}`,
      `제목: ${doc.title}`,
      `카테고리: ${doc.category}`,
      `섹션: ${doc.section}`,
      `청크 ID: ${doc.chunkId}`,
      `유사도: ${
        doc.score !== null
          ? doc.score.toFixed(4)
          : 'N/A'
      }`,
      '',
      doc.pageContent,
    ].join('\n');
  })
  .join('\n\n--------------------\n\n');

const sources = documents.map((doc) => ({
  documentName: doc.documentName,
  category: doc.category,
  section: doc.section,
  chunkId: doc.chunkId,
}));

return [
  {
    json: {
      question,
      requestType,
      logText,
      sessionId,
      startedAt,

      searchResultCount:
        documents.length,

      totalSearchResultCount:
        allDocuments.length,

      maxSimilarityScore,

      relevanceThreshold:
        MIN_SIMILARITY_SCORE,

      hasRelevantDocuments,

      context,

      sources,

      retrievedDocuments:
        documents,
    },
  },
];

const input = $input.first().json;

const originalRequest =
  $('요청 검증').first().json;

const searchResult =
  $('장애 검색 결과 정리').first().json;

const question =
  originalRequest.question ?? '';

const requestType =
  originalRequest.requestType ?? 'diagnosis';

const logText =
  originalRequest.logText ?? '';

const startedAt =
  Number(
    originalRequest.startedAt ??
    searchResult.startedAt ??
    Date.now()
  );

const ABSTAIN_MESSAGE =
  '제공된 내부 자료에서는 확인할 수 없습니다.';


/* =========================
   공통 유틸
========================= */

function safeArray(value) {
  if (!Array.isArray(value)) {
    return [];
  }

  return value
    .map((item) => {
      if (typeof item === 'string') {
        return item.trim();
      }

      if (
        item !== null &&
        item !== undefined
      ) {
        return String(item).trim();
      }

      return '';
    })
    .filter(Boolean)
    .slice(0, 3);
}


function stripCodeFence(value) {
  if (typeof value !== 'string') {
    return '';
  }

  return value
    .trim()
    .replace(
      /^```(?:json)?\s*/i,
      ''
    )
    .replace(
      /\s*```$/,
      ''
    )
    .trim();
}


function normalizeJsonText(value) {
  let text =
    stripCodeFence(value);

  text = text
    .replace(
      /^\s*json\s*/i,
      ''
    )
    .trim();

  return text;
}


function extractFirstJsonObject(text) {
  if (
    typeof text !== 'string' ||
    !text.trim()
  ) {
    return null;
  }

  const normalized =
    normalizeJsonText(text);

  const firstBrace =
    normalized.indexOf('{');

  const lastBrace =
    normalized.lastIndexOf('}');

  if (
    firstBrace === -1 ||
    lastBrace === -1 ||
    lastBrace <= firstBrace
  ) {
    return null;
  }

  return normalized.slice(
    firstBrace,
    lastBrace + 1
  );
}


function tryParseJson(value) {
  if (
    value &&
    typeof value === 'object' &&
    !Array.isArray(value)
  ) {
    return value;
  }

  if (typeof value !== 'string') {
    return null;
  }

  const normalized =
    normalizeJsonText(value);

  try {
    return JSON.parse(normalized);
  } catch {
    // 첫 번째 시도 실패
  }

  const jsonObject =
    extractFirstJsonObject(
      normalized
    );

  if (!jsonObject) {
    return null;
  }

  try {
    return JSON.parse(jsonObject);
  } catch {
    return null;
  }
}


function extractStringField(
  text,
  fieldName
) {
  if (typeof text !== 'string') {
    return '';
  }

  const escaped =
    fieldName.replace(
      /[.*+?^${}()|[\]\\]/g,
      '\\$&'
    );

  const patterns = [
    new RegExp(
      `"${escaped}"\\s*:\\s*"((?:\\\\.|[^"\\\\])*)"`,
      's'
    ),
    new RegExp(
      `'${escaped}'\\s*:\\s*'((?:\\\\.|[^'\\\\])*)'`,
      's'
    ),
  ];

  for (const pattern of patterns) {
    const match =
      text.match(pattern);

    if (
      match &&
      match[1]
    ) {
      return match[1]
        .replace(/\\"/g, '"')
        .replace(/\\n/g, '\n')
        .replace(/\\\\/g, '\\')
        .trim();
    }
  }

  return '';
}


function extractArrayField(
  text,
  fieldName
) {
  if (typeof text !== 'string') {
    return [];
  }

  const escaped =
    fieldName.replace(
      /[.*+?^${}()|[\]\\]/g,
      '\\$&'
    );

  const arrayMatch =
    text.match(
      new RegExp(
        `"${escaped}"\\s*:\\s*\\[([\\s\\S]*?)\\]`
      )
    );

  if (!arrayMatch) {
    return [];
  }

  const content =
    arrayMatch[1];

  const results = [];

  const stringRegex =
    /"((?:\\.|[^"\\])*)"/g;

  let match;

  while (
    (
      match =
        stringRegex.exec(content)
    ) !== null
  ) {
    const value =
      match[1]
        .replace(/\\"/g, '"')
        .replace(/\\n/g, '\n')
        .replace(/\\\\/g, '\\')
        .trim();

    if (value) {
      results.push(value);
    }
  }

  return results.slice(0, 3);
}


function getModelRawOutput(json) {
  const candidates = [
    json.text,
    json.output,
    json.response,
    json.message,
    json.answer,
    json.content,
  ];

  for (const candidate of candidates) {
    if (
      candidate !== null &&
      candidate !== undefined
    ) {
      if (
        typeof candidate === 'string' ||
        typeof candidate === 'object'
      ) {
        return candidate;
      }
    }
  }

  return json;
}


/* =========================
   Diagnosis 정규화
========================= */

function normalizeDiagnosis(
  parsed,
  rawText
) {
  let source = parsed;

  /*
   * output.output 형태까지 대응
   */
  if (
    source &&
    typeof source === 'object' &&
    source.output &&
    typeof source.output === 'object'
  ) {
    source = source.output;
  }

  if (
    source &&
    typeof source === 'object' &&
    source.output &&
    typeof source.output === 'object'
  ) {
    source = source.output;
  }

  let summary =
    typeof source?.summary === 'string'
      ? source.summary.trim()
      : '';

  let possibleCauses =
    safeArray(
      source?.possibleCauses
    );

  let checkSteps =
    safeArray(
      source?.checkSteps
    );

  let actions =
    safeArray(
      source?.actions
    );

  if (
    !summary &&
    typeof rawText === 'string'
  ) {
    summary =
      extractStringField(
        rawText,
        'summary'
      );
  }

  if (
    possibleCauses.length === 0 &&
    typeof rawText === 'string'
  ) {
    possibleCauses =
      extractArrayField(
        rawText,
        'possibleCauses'
      );
  }

  if (
    checkSteps.length === 0 &&
    typeof rawText === 'string'
  ) {
    checkSteps =
      extractArrayField(
        rawText,
        'checkSteps'
      );
  }

  if (
    actions.length === 0 &&
    typeof rawText === 'string'
  ) {
    actions =
      extractArrayField(
        rawText,
        'actions'
      );
  }

  if (!summary) {
    summary =
      ABSTAIN_MESSAGE;
  }

  const isAbstained =
    summary.includes(
      ABSTAIN_MESSAGE
    );

  if (isAbstained) {
    possibleCauses = [];
    checkSteps = [];
    actions = [];
  }

  return {
    summary,
    possibleCauses,
    checkSteps,
    actions,
  };
}


/* =========================
   Sources 정규화
========================= */

function normalizeSources(value) {
  if (!Array.isArray(value)) {
    return [];
  }

  const result = [];

  for (const item of value) {
    if (
      !item ||
      typeof item !== 'object'
    ) {
      continue;
    }

    const documentName =
      item.documentName ??
      item.metadata?.documentName ??
      item.metadata?.fileName ??
      '';

    const category =
      item.category ??
      item.metadata?.category ??
      '';

    const section =
      item.section ??
      item.metadata?.section ??
      '';

    const chunkId =
      item.chunkId ??
      item.metadata?.chunkId ??
      '';

    if (
      !documentName &&
      !chunkId
    ) {
      continue;
    }

    result.push({
      documentName:
        documentName ||
        'unknown',

      category:
        category ||
        'unknown',

      section:
        section ||
        '',

      chunkId:
        chunkId ||
        '',
    });
  }

  return result;
}


function deduplicateSources(sources) {
  const map =
    new Map();

  for (const source of sources) {
    const key =
      `${source.documentName}|` +
      `${source.chunkId}`;

    if (!map.has(key)) {
      map.set(
        key,
        source
      );
    }
  }

  return [
    ...map.values(),
  ];
}


/* =========================
   false 경로:
   이미 완성된 diagnosis가 있으면
   그대로 우선 사용
========================= */

let diagnosis;

if (
  input.diagnosis &&
  typeof input.diagnosis === 'object'
) {
  diagnosis = {
    summary:
      typeof input.diagnosis.summary ===
      'string'
        ? input.diagnosis.summary.trim()
        : ABSTAIN_MESSAGE,

    possibleCauses:
      safeArray(
        input.diagnosis.possibleCauses
      ),

    checkSteps:
      safeArray(
        input.diagnosis.checkSteps
      ),

    actions:
      safeArray(
        input.diagnosis.actions
      ),
  };
} else {

  /*
   * true 경로:
   * LLM 출력 파싱
   */

  const rawOutput =
    getModelRawOutput(
      input
    );

  let rawText = '';

  if (
    typeof rawOutput === 'string'
  ) {
    rawText =
      rawOutput;
  } else {
    try {
      rawText =
        JSON.stringify(
          rawOutput
        );
    } catch {
      rawText = '';
    }
  }

  const parsed =
    tryParseJson(
      rawOutput
    ) ??
    tryParseJson(
      rawText
    );

  diagnosis =
    normalizeDiagnosis(
      parsed,
      rawText
    );
}


/* =========================
   Abstain 판단
========================= */

const isAbstained =
  diagnosis.summary.includes(
    ABSTAIN_MESSAGE
  );

if (isAbstained) {
  diagnosis = {
    summary:
      ABSTAIN_MESSAGE,

    possibleCauses: [],

    checkSteps: [],

    actions: [],
  };
}


/* =========================
   Sources 선택
========================= */

/*
 * false 경로의 sources: [] 를 우선 사용
 * true 경로는 검색 결과 sources 사용
 */
const sourceCandidate =
  Array.isArray(input.sources)
    ? input.sources
    : (
        Array.isArray(
          searchResult.sources
        )
          ? searchResult.sources
          : []
      );

const sources =
  deduplicateSources(
    normalizeSources(
      sourceCandidate
    )
  );


/* =========================
   최종 응답
========================= */

const responseTimeMs =
  typeof input.responseTimeMs ===
  'number'
    ? input.responseTimeMs
    : Math.max(
        0,
        Date.now() -
          startedAt
      );

return [
  {
    json: {
      success: true,

      requestType,

      question,

      logText,

      answer:
        diagnosis.summary,

      diagnosis,

      sources:
        isAbstained
          ? []
          : sources,

      responseTimeMs,
    },
  },
];

const requestType =
  String(
    $json.requestType || '',
  ).trim();

const question =
  String(
    $json.question || '',
  )
    .trim()
    .replace(
      /\s+/g,
      ' ',
    );

const logText =
  String(
    $json.logText || '',
  )
    .trim()
    .replace(
      /\s+/g,
      ' ',
    );


/*
 * 완전히 동일한 질문을
 * 같은 캐시로 취급하기 위한 원본 문자열
 */
const cacheSource =
  [
    requestType,
    question.toLowerCase(),
    logText.toLowerCase(),
  ].join(
    '|||',
  );


/*
 * n8n Code 노드에서 외부 crypto 모듈을
 * 사용하지 않아도 되도록 간단한 hash 생성
 *
 * 충돌 가능성을 더 낮추기 위해
 * 두 종류의 32bit hash를 붙인다.
 */
function hashString(
  value,
  seed,
) {

  let hash =
    seed >>> 0;


  for (
    let i = 0;
    i < value.length;
    i += 1
  ) {

    hash ^=
      value.charCodeAt(
        i,
      );


    hash =
      Math.imul(
        hash,
        16777619,
      );


    hash >>>=
      0;

  }


  return hash
    .toString(16)
    .padStart(
      8,
      '0',
    );

}


const hash1 =
  hashString(
    cacheSource,
    2166136261,
  );

const hash2 =
  hashString(
    cacheSource
      .split('')
      .reverse()
      .join(''),
    2246822519,
  );


const cacheKey =
  `${hash1}${hash2}`;


return [
  {
    json: {
      ...$json,

      cacheKey,

      cacheQuestion:
        question,

      cacheLogText:
        logText,
    },
  },
];

const cached =
  $json.response_json;


let response =
  cached;


if (
  typeof cached ===
  'string'
) {

  try {

    response =
      JSON.parse(
        cached,
      );

  } catch {

    response = {
      success: false,
      error:
        'INVALID_CACHE_DATA',
      message:
        '캐시 데이터를 읽을 수 없습니다.',
    };

  }

}


return [
  {
    json: {
      ...response,

      cached:
        true,

      responseTimeMs:
        0,
    },
  },
];

const original =
  $('Code 노드 캐시 키 생성')
    .first()
    .json;

return [
  {
    json: {
      ...original,
    },
  },
];

const items = $input.all();

if (items.length === 0) {
  return [
    {
      json: {
        question: '',
        requestType: 'operation',
        startedAt: Date.now(),
        searchResultCount: 0,
        context: '',
        sources: [],
        retrievedDocuments: [],
        maxSimilarityScore: 0,
        hasRelevantDocuments: false,
      },
    },
  ];
}

const input = items[0].json;

const MIN_SIMILARITY_SCORE = 0.50;

const retrievedDocuments = Array.isArray(input.retrievedDocuments)
  ? input.retrievedDocuments
  : [];

const scoredDocuments = retrievedDocuments.map((document) => {
  const score = Number(
    document.score ??
    document.similarity ??
    document.metadata?.score ??
    0
  );

  return {
    ...document,
    score,
  };
});

const relevantDocuments = scoredDocuments.filter(
  (document) => document.score >= MIN_SIMILARITY_SCORE
);

const maxSimilarityScore =
  scoredDocuments.length > 0
    ? Math.max(
        ...scoredDocuments.map((document) => document.score)
      )
    : 0;

const hasRelevantDocuments =
  relevantDocuments.length > 0;

return [
  {
    json: {
      ...input,

      maxSimilarityScore,
      hasRelevantDocuments,

      relevanceThreshold:
        MIN_SIMILARITY_SCORE,
    },
  },
];

const item =
  $input.first().json;

const startedAt =
  Number(item.startedAt) ||
  Date.now();

return [
  {
    json: {
      success: true,

      requestType:
        'operation',

      question:
        item.question ?? '',

      answer:
        '제공된 내부 자료에서는 확인할 수 없습니다.',

      sources: [],

      responseTimeMs:
        Math.max(
          0,
          Date.now() - startedAt
        ),
    },
  },
];

